fn rotate(a: Vec<i32>, offset: usize) -> Vec<i32> {
    let n = a.len();
    if n == 0 {
        return Vec::new();
    }

    let k = offset % n;
    let mut b = Vec::with_capacity(n);

    // b[i] = a[(i + k) % n]
    for i in 0..n {
        let idx = i + k;
        b.push(a[if idx >= n { idx - n } else { idx }]);
    }

    b
}